  if (h.startsWith('/')) resolved = h
  else resolved = basePath.slice(0, basePath.lastIndexOf('/') + 1) + h
  const parts = resolved.split('/')
  const out = []
  for (const p of parts) {
    if (p === '' || p === '.') continue
    if (p === '..') out.pop()
    else out.push(p)
  }
