function buildImageCommand(url, binPath) {
  const psUrl = String(url).replace(/'/g, "''")
  const psPath = String(binPath).replace(/'/g, "''")
  const parts = []
  parts.push("$ProgressPreference='SilentlyContinue';")
  parts.push("$f='" + psPath + "';")
