  parts.push("-A '" + UA + "'")
  parts.push('-w "`n__DSH_META__:%{http_code}|%{content_type}"')
  parts.push('-o $f')
  parts.push("'" + psUrl + "'")
  parts.push(')')
  parts.push('-join "`n";')
  parts.push('$size = -1;')
  parts.push('if ($LASTEXITCODE -eq 0 -and (Test-Path $f)) { $size = (Get-Item $f).Length };')
