    statusCode: metaM ? Number(metaM[1]) : 0,
    contentType: metaM ? String(metaM[2] || '') : '',
    size: sizeM ? Number(sizeM[1]) : -1,
    filePath: fileM ? String(fileM[1]).trim() : binPath
  }
}

